head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/listing_iss_common.js");
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo, scwin.vListProcsStatCd;
scwin.vSecugrpID, scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.TR_JOB;
scwin.visuShrsLabelNm = "주식";
scwin.gPrtdepoSeq;
scwin.vScrenID = "ULDSTF92026.xml";
scwin.strCbd_NPARVALSTK_YN = "N^아니오,Y^예";
scwin.vPRELM_INVSTG_BZ_PROCS_NO;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_searchCode = function() {
    /*
    00443 - 통화ISO코드 
    */
    var arrCid = [{
        cid: "CURR_ISO_CD",
        cnm: "cmb_CURR_ISO_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='CURR_ISO_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.resizeToWin = function() {
    //frame.Width = 280;
    //frame.Height = 420;
    $c.stf.MoveCenterOfParent();
};
scwin.fn_initForm = function(initTyp) {
    if (initTyp == 'I') {
        img_ISU_CD.src = "../img/btn_search.gif";
        img_ISU_CD.setDisabled(false);
    } else if (initTyp == 'X') {
        img_ISU_CD.src = "../img/btn_search_d.gif";
        img_ISU_CD.setDisabled(true);
    }
};
scwin.fn_setSumblComponent = function() {
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == '1') {
        txb_ISU_ENG_SYMBL.setReadOnly(false);
        txb_ISU_ENG_SYMBL.ReadOnlyBackgroundColor = '#ffffff';
        $c.stf.showObj(img_ISU_ENG_SYMBL, true);
    } else {
        txb_ISU_ENG_SYMBL.setReadOnly(true);
        txb_ISU_ENG_SYMBL.ReadOnlyBackgroundColor = '#b9d4f7';
        $c.stf.showObj(img_ISU_ENG_SYMBL, false);
    }
};
scwin.fn_setInitLabel = function() {
    if (scwin.vSecugrpID == SECUGRP_ID_DR) {
        scwin.visuShrsLabelNm = "DR";
        $c.stf.setObjectValue(lb_PARVAL, 'DR당액면가');
        $c.stf.setObjectValue(lb_BF_ACC_ISU_SHRS, '변경전 상장DR수');
        $c.stf.setObjectValue(lb_ISU_SHRS, '증감상장DR수');
        $c.stf.setObjectValue(lb_ACC_ISU_SHRS, '변경후 상장DR수');
        $c.stf.showObj(panel_PARVAL, false);
        $c.stf.showObj(panel_ISU_CAP, false);
    } else {
        scwin.visuShrsLabelNm = "주식";
        $c.stf.showObj(panel_PARVAL, true);
        $c.stf.showObj(panel_ISU_CAP, true);
    }
    if (scwin.vSecugrpID == SECUGRP_ID_DR || scwin.vSecugrpID == SECUGRP_ID_FS) {
        edt_PARVAL.MaxDecimalPlace = 3;
        edt_ISU_CAP.MaxDecimalPlace = 3;
    } else {
        edt_PARVAL.MaxDecimalPlace = 0;
        edt_ISU_CAP.MaxDecimalPlace = 0;
    }
};
scwin.fn_SetComboCode = function() {
    cmb_NPARVALSTK_YN.CBData = scwin.strCbd_NPARVALSTK_YN;
    cmb_NPARVALSTK_YN.setSelectedIndex(0);
    $c.stf.showObj(edt_PARVAL, true);
    $c.stf.showObj(edt_PER1STK_CAP, false);
    $c.stf.setObjectValue(edt_PER1STK_CAP, "0");
    var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listStkIsuRsnCd&inputMessageId=STK_ISU_RSN_CD_OUT";
    url += "&LD_MKT_TP_CD=" + scwin.vSPOT_ISU_TRD_MKT_TP_CD;
    //발행사유코드
    dts_STK_ISU_RSN_CD.DataID = encodeURI(url);
    dts_STK_ISU_RSN_CD.Reset();
};
scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = scwin.vSecugrpID;
    arrPar[1] = $c.stf.getObjectValue(txb_ISUR_CD); // 코드값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    //var dbClickYn =  arrPar[0].DBCLICKYN;
    if (arrPar[0].ISU_CD != "") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_KOR_NM.setValue(arrPar[0].ISU_KOR_NM);
        txb_ISU_KOR_ABBRV.setValue(arrPar[0].ISU_KOR_ABBRV);
        txb_ISU_ENG_NM.setValue(arrPar[0].ISU_ENG_NM);
        txb_ISU_ENG_ABBRV.setValue(arrPar[0].ISU_ENG_ABBRV);
        txb_ISU_SRT_CD.setValue(arrPar[0].ISU_SRT_CD);
        txb_ISU_ENG_SYMBL.setValue(arrPar[0].ISU_ENG_SYMBL);
        $c.stf.setObjectValue(cmb_CURR_ISO_CD, arrPar[0].CURR_ISO_CD);
        if (scwin.vSecugrpID == SECUGRP_ID_DR) {
            $c.stf.setObjectValue(cmb_STKCERT_KIND_CD, 'KDR'); //주식의종류코드를 셋팅

        } else if (scwin.vSecugrpID == SECUGRP_ID_FS) {
            $c.stf.setObjectValue(cmb_STKCERT_KIND_CD, '000'); //주식의종류코드를 셋팅

        } else {
            $c.stf.setObjectValue(cmb_STKCERT_KIND_CD, $c.stf.getObjectValue(txb_ISU_CD).substring(8, 11)); //주식의종류코드를 셋팅

        }
        scwin.fn_nprefstk_read_sync(txb_ISU_CD.getValue());
        scwin.fn_bf_read_sync();
    }
};



/**
 * 변경전 주식수, 자본금 가져오기
 */
scwin.fn_bf_read_sync = function() {
    var url = "/Newlisting.do?method=selectManagement&inputMessageId=BF_STKCERT_ISU_DTL_OUT";
    url += "&DIV_IDX=" + DIV_R_LISTING_BF_ISU;
    url += "&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
    url += "&LIST_DD=" + $c.stf.getObjectValue(edt_LIST_DD);
    dtsObj.DataID = encodeURI(url);
    dtsObj.reset();
    if (dtsObj.getTotalRow() > 0) {
        $c.stf.setObjectValue(edt_BF_ACC_ISU_SHRS, dtsObj.getCellData(1, "BF_ACC_ISU_SHRS"));
        $c.stf.setObjectValue(edt_BF_ACC_ISU_CAP, dtsObj.getCellData(1, "BF_ACC_ISU_CAP"));
    } else {
        //신규건...
        $c.stf.setObjectValue(edt_BF_ACC_ISU_SHRS, 0);
        $c.stf.setObjectValue(edt_BF_ACC_ISU_CAP, 0);
    }
};
scwin.fn_nprefstk_read_sync = function(isucd) {
    var url = "/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchIsuIssChgList" + "&DIV_IDX=" + DIV_IDX_ISS_NEWPREFSTK_STK_HIST + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&ISU_CD=" + isucd;
    dts_KINDSTK.DataID = encodeURI(url);
    dts_KINDSTK.Reset();
    if (dts_KINDSTK.getTotalRow() > 0) {
        dts_Isu.setCellData(1, "PREFSTK_ISU_DD", dts_KINDSTK.getCellData(1, "ISU_DD"));
        dts_Isu.setCellData(1, "PREFSTK_DIV_RT", dts_KINDSTK.getCellData(1, "PREFSTK_DIV_RT"));
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_YYS", dts_KINDSTK.getCellData(1, "PREFSTK_CONTIN_DEADLINE_YYS"));
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_MM", dts_KINDSTK.getCellData(1, "PREFSTK_CONTIN_DEADLINE_MM"));
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_DYS", dts_KINDSTK.getCellData(1, "PREFSTK_CONTIN_DEADLINE_DYS"));
        dts_Isu.setCellData(1, "PREFSTK_END_DD", dts_KINDSTK.getCellData(1, "PREFSTK_END_DD"));
        dts_Isu.setCellData(1, "INDEFINPD_YN", dts_KINDSTK.getCellData(1, "INDEFINPD_YN"));
    } else {
        dts_Isu.setCellData(1, "PREFSTK_ISU_DD", '');
        dts_Isu.setCellData(1, "PREFSTK_DIV_RT", '');
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_YYS", '');
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_MM", '');
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_DYS", '');
        dts_Isu.setCellData(1, "PREFSTK_END_DD", '');
        dts_Isu.setCellData(1, "INDEFINPD_YN", '');
    }
};
scwin.fn_setCheckboxData = function(obj, val) {
    if (val == 'Y') {
        obj.setValue(1);
    } else {
        obj.setValue(0);
    }
};
scwin.fn_getCheckboxData = function(obj) {
    if (obj.checked) {
        return 'Y';
    } else {
        return 'N';
    }
};
scwin.fn_read_sync = function() {
    var url = "/KindStk.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readKindStkIsuDtl&inputMessageId=KIND_STK_NEWLIST_SEARCH_OUT";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.Reset();
    scwin.fn_setCheckboxData(chk_INDEFINPD_YN, dts_Isu.getCellData(1, "INDEFINPD_YN"));
    if (dts_Isu.getCellData(1, "NPARVALSTK_YN") == 'Y') {
        $c.stf.showObj(edt_PARVAL, false);
        $c.stf.showObj(edt_PER1STK_CAP, true);
        $c.stf.setObjectValue(edt_PARVAL, "0");
    } else {
        $c.stf.showObj(edt_PARVAL, true);
        $c.stf.showObj(edt_PER1STK_CAP, false);
        $c.stf.setObjectValue(edt_PER1STK_CAP, "0");
    }

    //		fn_setCheckboxData(chk_PARTCTP_YN, dts_Isu.NameValue(1, "PARTCTP_YN"));

    //		fn_setCheckboxData(chk_ACCTP_YN, dts_Isu.NameValue(1, "ACCTP_YN"));

    //		fn_setCheckboxData(chk_NDIVTM_VOTERGHT_YN, dts_Isu.NameValue(1, "NDIVTM_VOTERGHT_YN"));

};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[법인코드] 항목값이  없습니다.");
        txb_ISUR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) == "") {
        $c.win.alert("[상장방식]을 선택하세요.");
        cmb_LIST_METHD_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_SRT_CD) == "") {
        $c.win.alert("[종목단축코드]항목값이  없습니다."); //txb_ISU_SRT_CD.focus();return false;

    }
    if ($c.stf.getObjectValue(txb_ISU_KOR_NM) == "") {
        $c.win.alert("[한글종목명]을 입력하세요.");
        txb_ISU_KOR_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_KOR_NM, 60, "한글종목명")) return false;
    if ($c.stf.getObjectValue(txb_ISU_KOR_ABBRV) == "") {
        $c.win.alert("[한글종목약명]을 입력하세요.");
        txb_ISU_KOR_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_KOR_ABBRV, 30, "한글종목약명")) return false;
    if ($c.stf.getObjectValue(txb_ISU_ENG_NM) == "") {
        $c.win.alert("[영문종목명]을 입력하세요.");
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 60, "영문종목명")) return false;
    if ($c.stf.getObjectValue(txb_ISU_ENG_ABBRV) == "") {
        $c.win.alert("[영문종목약명]을 입력하세요.");
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 30, "영문종목약명")) return false;
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "1") {
        if ($c.stf.getObjectValue(txb_ISU_ENG_SYMBL) == "") {
            $c.win.alert("[영문종목심볼]을 입력하세요.");
            txb_ISU_ENG_SYMBL.focus();
            return false;
        }
        if (!$c.lc.fn_chkIsuSymblDoubleInput($c.stf.getObjectValue(txb_ISU_ENG_SYMBL), $c.stf.getObjectValue(txb_ISU_CD), dts_Symbl)) {
            $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
            return false;
        }
    }
    if ($c.stf.getObjectValue(edt_LIST_DD) == "") {
        $c.win.alert("[상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (vCurDate >= $c.stf.getObjectValue(edt_LIST_DD)) {
        $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_ISU_DD) == "") {
        $c.win.alert("[발행일]을 입력하세요.");
        edt_ISU_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_ISU_RND) == "") {
        $c.win.alert("[발행회차]를 입력하세요.");
        edt_ISU_RND.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_STKCERT_KIND_CD) == "") {
        $c.win.alert("[주식의종류]를 선택하세요.");
        cmb_STKCERT_KIND_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "") {
        $c.win.alert("[주식발행사유]를 선택하세요.");
        cmb_STK_ISU_RSN_CD.focus();
        return false;
    }

    ///*
    if (scwin.vSecugrpID != SECUGRP_ID_MF && scwin.vSecugrpID != SECUGRP_ID_IF && scwin.vSecugrpID != SECUGRP_ID_DR) {
        if ($c.stf.getObjectValue(edt_PARVAL) == "") {
            $c.win.alert("[액면가]을 입력하세요.");
            edt_PARVAL.focus();
            return false;
        }

        //if (! fn_checkNumber(edt_PARVAL, '액면가')) return false;

    }
    if ($c.stf.getObjectValue(edt_ISU_PRC) == "") {
        $c.win.alert("[발행가]을 입력하세요.");
        edt_ISU_PRC.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_ISU_SHRS) == "") {
        $c.win.alert("[증감" + scwin.visuShrsLabelNm + "수]을 입력하세요.");
        edt_ISU_SHRS.focus();
        return false;
    }
    if (scwin.vSecugrpID != SECUGRP_ID_DR) {
        if ($c.stf.getObjectValue(edt_ISU_CAP) == "") {
            $c.win.alert("[증감 상장자본금]을 입력하세요.");
            edt_ISU_CAP.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_ACC_ISU_SHRS) == "") {
            $c.win.alert("[변경후 상장" + scwin.visuShrsLabelNm + "수]을 입력하세요.");
            edt_ACC_ISU_SHRS.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_ACC_ISU_SHRS) == "0") {
            $c.win.alert("[변경후 상장" + scwin.visuShrsLabelNm + "수]값이 '0' 입니다. \n[증감 상장" + scwin.visuShrsLabelNm + "수]가 올바르게 입력되었는지 확인바랍니다.");
            edt_ACC_ISU_SHRS.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_ACC_ISU_CAP) == "") {
            $c.win.alert("[변경후 상장자본금]을 입력하세요.");
            edt_ACC_ISU_CAP.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_ACC_ISU_CAP) == "0") {
            $c.win.alert("[변경후 상장자본금]값이 '0' 입니다. '\n[증감 상장자본금]이 올바르게 입력되었는지 확인바랍니다.");
            edt_ACC_ISU_CAP.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(edt_DIV_RECK_DD1) == "") {
        $c.win.alert("[배당기산일1]을 입력하세요.");
        edt_DIV_RECK_DD1.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_NPARVALSTK_YN) == "Y") {
        var PER1STK_CAP = eval(parseFloat($c.stf.getObjectValue(edt_PER1STK_CAP)));
        var ISU_PRC = eval(parseFloat($c.stf.getObjectValue(edt_ISU_PRC)));
        if (PER1STK_CAP > ISU_PRC) {
            $c.win.alert('개별주당자본금은  발행가 이하로 입력해 주십시오.');
            edt_PER1STK_CAP.focus();
            return false;
        }
        if (PER1STK_CAP < (ISU_PRC * 0.5)) {
            $c.win.alert('개별주당자본금은 발행가의 50% 이상으로 입력해 주십시오');
            edt_PER1STK_CAP.focus();
            return false;
        }
    }
    return true;
};
scwin.fn_save = function() {
    if (dts_PRTDEPO.getTotalRow() == "0") {
        var msg = "의무보유내역이 입력되지 않았습니다!\n의무보유대상이 있으면 취소를 누르고 해당내역을 입력하여 주십시오.\n그대로 진행하기를 원하시면 확인을 누르십시오.";
        var res = window.confirm(msg);
        if (!res) {
            return;
        }
    }
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);

        //alert("[bz_procs_no]"+bz_procs_no);
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo); /*ORG SRC: dts_Isu.UserStatus(1) = TB_JOB_INSERT;*/ X = TB_JOB_INSERT;
            scwin.fn_trs();
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return; /*ORG SRC: dts_Isu.UserStatus(1) = TB_JOB_UPDATE;*/ X = TB_JOB_UPDATE;
        scwin.fn_trs();
    }
};
scwin.fn_getCheckboxNprefStk = function(obj, stk_knd) {
    var val;
    if (obj.checked) {
        val = '2';
    } else {
        if (stk_knd == "000" || stk_knd == "KDR") {
            val = '0';
        } else {
            val = '1';
        }
    }
    return val;
};
scwin.fn_trs = function() {
    var vScrenProcTpCd;
    var listProcsStatCd;
    if (scwin.TR_JOB == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
        listProcsStatCd = "20";
    } else if (scwin.TR_JOB == "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
        listProcsStatCd = "";
    } else if (scwin.TR_JOB == "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
        listProcsStatCd = "50";
    }
    var VListBzTpCd = LIST_BZ_TP_CD_100; //신규상장

    dts_Isu.setCellData(1, "LIST_BZ_TP_CD", VListBzTpCd);
    dts_Isu.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
    //dts_Isu.NameString(1, "NPARVALSTK_YN") = getObjectValue(cmb_NPARVALSTK_YN);
    dts_Isu.setCellData(1, "INDEFINPD_YN", scwin.fn_getCheckboxData(chk_INDEFINPD_YN));
    dts_Isu.setCellData(1, "LIST_PROCS_STAT_CD", listProcsStatCd);
    dts_Isu.setCellData(1, "SPOT_ISU_TRD_MKT_TP_CD", js_market);
    for (i = 1; i <= dts_PRTDEPO.getTotalRow(); i++) {
        dts_PRTDEPO.setCellData(i, "BZ_PROCS_NO", scwin.vBzProcsNo);
        dts_PRTDEPO.setCellData(i, "SEQ", i); //저장하기 위해 이벤트를 발생시킨다.

    }
    trs_Save.Action = $c.lc.fn_encodeNSession("/KindStk.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveKindStkIsu");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput_1=dts_Isu, I:pInput_2=dts_PRTDEPO)";
    trs_Save.Parameters = "BZ_PROCS_NO=" + scwin.vBzProcsNo;
    ",LD_MKT_TP_CD=" + js_market + ",ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + ",LIST_DD=" + $c.stf.getObjectValue(edt_LIST_DD) + ",LIST_PROCS_STAT_CD=" + listProcsStatCd;
    trs_Save.Post();
};
scwin.fn_delete = function() {
    scwin.TR_JOB = 'D';
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.


    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    /*ORG SRC: dts_Isu.UserStatus(1) = TB_JOB_DELETE;*/
    X = TB_JOB_DELETE;
    scwin.fn_trs();
};
