scwin.gform_onload = function() {
    var parentWin = $c.frame.path("../");
    var vCoBzProcsNo = parentWin.scwin.vBzProcsNo;
    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.vSecugrpID = $c.stf.getObjectValue(parentWin.cmb_SECUGRP_ID);
    scwin.vPRELM_INVSTG_BZ_PROCS_NO = parentWin.dts_Corp.getCellData('1', "PRELM_INVSTG_BZ_PROCS_NO");
    scwin.vSPOT_ISU_TRD_MKT_TP_CD = $c.stf.getObjectValue(parentWin.cmb_SPOT_ISU_TRD_MKT_TP_CD);
    $c.stf.setObjectValue(txb_ISUR_CD, $c.stf.getObjectValue(parentWin.txb_ISUR_CD));
    $c.stf.setObjectValue(txb_COM_NM, $c.stf.getObjectValue(parentWin.txb_COM_NM));
    rowPos = parentWin.dts_Isu.getFocusedRowIndex();

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제


    //resizeToWin() ;
    scwin.fn_searchCode();
    scwin.fn_SetComboCode();
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    scwin.fn_setInitLabel();
    scwin.fn_setSumblComponent();
    if (scwin.vBzProcsNo != "") {
        scwin.fn_read_sync();
        // 보호예수읽어온다
        scwin.fn_prtdepo_read_sync();
    } else {
        dts_Isu.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=KIND_STK_STKCERT_ISU_DTL_INOUT";
        dts_Isu.reset();
        dts_Isu.insertRow();
        if (vCoBzProcsNo == "") {
            $c.win.alert("먼저 회사정보를 입력후 종목정보를 입력바랍니다.");
            buttonSet.setErrorStatus(); //disable 시킨다.

        } else {
            $c.stf.setObjectValue(edt_LIST_DD, $c.stf.getObjectValue(parentWin.edt_LIST_DD));
            var vlistClssCd = $c.stf.getObjectValue(parentWin.cmb_LIST_CLSS_CD);
            var vListMethdTpCd;
            var vListMethdTpUpCd = vlistClssCd.substring(0, 1);
            vListMethdTpCd = LIST_METHD_TP_CD_4;
            $c.stf.setObjectValue(cmb_LIST_METHD_TP_CD, vListMethdTpCd);
        }
        var vCurDate = $c.ut.cGetToday("yyyymmdd");
        if ($c.stf.getObjectValue(edt_LIST_DD) <= vCurDate) {
            buttonSet.setErrorStatus(); //disable 시킨다.

        }
        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == '1') {
            //자동 settiong
            $c.stf.showObj(panel_ISU_ENG_SYMBL, true);
            $c.stf.setObjectValue(txb_ISU_ENG_SYMBL, $c.stf.getObjectValue(parentWin.edt_ISUR_SYMBL));
        } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == '2') {
            $c.stf.showObj(panel_ISU_ENG_SYMBL, false);
        }

        // 보호예수초기화
        scwin.fn_prtdepo_read_sync_setHeader();
    }
};
